import{_ as a,o as i,c as s,a2 as n}from"./chunks/framework.CDpkVv68.js";const p=JSON.parse('{"title":"Estado de la magia y preguntas abiertas","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/magic/status-and-open-questions.md","filePath":"es/game-design/magic/status-and-open-questions.md"}'),t={name:"es/game-design/magic/status-and-open-questions.md"};function o(r,e,d,c,l,m){return i(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="magic-status-and-open-questions" tabindex="-1">Estado de la magia y preguntas abiertas <a class="header-anchor" href="#magic-status-and-open-questions" aria-label="Enlace permanente a &quot;Estado de la magia y preguntas abiertas&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; las decisiones enumeradas siguen Sin resolver. Los fundamentos existentes en estado Aceptado conservan su alcance. <strong>Implementación:</strong> no se ha establecido ninguna implementación de gameplay del Batch 04. <strong>Disponibilidad:</strong> no establecida para este rediseño. <strong>Verificación:</strong> solo conciliación documental, no validación en ejecución. <strong>Revisado:</strong> 2026-10-09 respecto al Batch 04 y al <a href="/Syrolands-Public/es/game-design/magic.html">diseño mágico anterior</a>.</p><p><a href="/Syrolands-Public/es/guide/magic/overview.html">Guía del jugador</a> · <a href="/Syrolands-Public/es/game-design/magic.html">Panorama de magia</a> · <a href="/Syrolands-Public/es/game-design/magic/status-and-open-questions.html">Estado y preguntas abiertas</a></p><h2 id="status-and-ownership" tabindex="-1">Estado y responsabilidad <a class="header-anchor" href="#status-and-ownership" aria-label="Enlace permanente a &quot;Estado y responsabilidad&quot;">​</a></h2><p>El Batch 04 es diseño en estado Propuesto, no entrega de gameplay. No se ha establecido que Active Memory, Familiarity, lectura de libros en combate, omisión de consulta mediante pergaminos, reactivos rediseñados, variantes de Inscription y efectos visuales modulares estén implementados o disponibles en juego. La autoridad del servidor, anatomía independiente, Hits globales frente a integridad local y Local Trauma separado, ya aceptados, conservan su alcance; el experimento cuerpo a cuerpo no valida la magia.</p><p>El <a href="/Syrolands-Public/es/game-design/magic.html">panorama</a> define instituciones, ejecución/Mastery de Magery, Meditation/Concentration, lanzamiento localizado, componentes de lanzamiento y propuestas anteriores de tradiciones prohibidas. Las páginas específicas enlazadas definen Core Patterns, variantes, memoria, materiales físicos, Inscription y gramática visual. Las URL de encabezados anteriores siguen utilizables.</p><h2 id="reconciliation-register" tabindex="-1">Registro de conciliación <a class="header-anchor" href="#reconciliation-register" aria-label="Enlace permanente a &quot;Registro de conciliación&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fuente / solapamiento</th><th>Tratamiento y conflicto restante</th></tr></thead><tbody><tr><td>Conocimiento mágico, maestros y academias anteriores</td><td>Conservados. Los Core Patterns aclaran la identidad estable; el descubrimiento sigue separado de la habilidad de ejecución</td></tr><tr><td>Mastery frente a Familiarity</td><td>Conservar Mastery más amplia por disciplina/afinidad; la práctica por Core Pattern es una capa distinta fuera del límite de habilidades. La interacción sigue abierta</td></tr><tr><td>Configuraciones anteriores de modificadores preparados</td><td>Conservar la propuesta y ampliarla con Active Memory; un núcleo aprendido/memorizado no decide el acceso a todas sus variantes</td></tr><tr><td>Enseñanza y copia de pergaminos</td><td>Los ordinarios otorgan ejecución temporal, no aprendizaje permanente. Los artefactos de enseñanza del Batch 04 requieren una política explícita separada; no borrar la restricción previa de pergaminos normales comerciables de aprendizaje</td></tr><tr><td>Protección del libro personal</td><td>Conservar conocimiento permanente; la propuesta más reciente distingue la representación personal de libros físicos raros saqueables. El mecanismo exacto de sustitución/conservación sigue abierto; no se elige bendición/estado Sacred</td></tr><tr><td>Franjas de habilidad y aprendizaje desde cero del Batch 02</td><td>La progresión compartida sigue siendo la referencia. Los bloques mágicos de +5 y ejemplos de 55–60 el primer día siguen siendo ilustrativos; equilibrar fundamentos fiables frente al fallo de hechizos avanzados difíciles requiere balance, no sustitución automática</td></tr><tr><td>Batch 02: ausencia de 120 ordinario / técnicas</td><td>Magery 100 es dominio técnico; conocimiento, escuelas, modificadores, práctica e Inscription amplían la progresión. No se migra límite ni catálogo</td></tr><tr><td>INT del Batch 02</td><td>Memoria/complejidad es una función cognitiva propuesta más fuerte; relaciones y fórmulas INT–maná siguen sin resolverse</td></tr><tr><td>Presión, extremidades y ejecución del jugador del Batch 03</td><td>Vincular con Concentration existente y perfiles de hechizos localizados. Fatiga, movimiento, golpes contundentes/aturdimiento y lesiones son candidatos; ningún hechizo hereda automáticamente fórmulas de trauma cuerpo a cuerpo</td></tr><tr><td>Conflicto de controles reactivos del Batch 03</td><td>La interacción física con libros no resuelve ni sustituye la base aceptada de combate cuerpo a cuerpo automático; el ataque manual obligatorio sigue sin resolverse por separado</td></tr><tr><td>Profesiones del Batch 01</td><td>Inscription usa habilidad/técnica/vía, Codex, secretos, enseñanza, producción, encargos y reputación. Alchemy puede procesar reactivos; recetas detalladas y requisitos entre habilidades siguen abiertos</td></tr><tr><td>Equipo y propuestas Sacred/Resonant</td><td>Preservar pérdida significativa y reemplazabilidad. Reactivos/pergaminos materiales y libros físicos valiosos conllevan riesgo; sin seguro amplio ni regla que impida caer a conjuntos sagrados</td></tr><tr><td>Servidor/cliente heredados</td><td>La herencia documentada previamente y las áreas no revisadas se separan en los límites de evidencia técnica; presencia de código no equivale a implementación del Batch 04</td></tr></tbody></table><h2 id="unresolved-decisions" tabindex="-1">Decisiones Sin resolver <a class="header-anchor" href="#unresolved-decisions" aria-label="Enlace permanente a &quot;Decisiones Sin resolver&quot;">​</a></h2><ul><li>Escala de Familiarity, reglas de progreso, límites antimacro/automatización y relación con Mastery más amplia.</li><li>Fórmula de capacidad de Active Memory, INT frente a maná, coste de complejidad de hechizos y tiempo de preparación de memorización.</li><li>Contribución de Meditation, representación/matemáticas de Concentration, recuperación y demoras exactas de consulta.</li><li>Consulta asistida por atajos sin trivializar la interacción física; experiencia de navegación de páginas, información de memoria/Familiarity en interfaz, accesibilidad y reasignación.</li><li>Reglas de memoria de variantes, cantidades de modificadores mayores/menores y restricciones de compatibilidad/acumulación.</li><li>Familias/fórmulas de reactivos, sustitución y consumo en acciones fallidas/interrumpidas.</li><li>Velocidad de lanzamiento/consulta de pergaminos y reglas de consumo; distinción entre pergaminos de enseñanza y de lanzamiento.</li><li>Límite de persistencia física/conocimiento del libro personal, sustitución y reglas de botín para grimorios raros.</li><li>Catálogo de técnicas de Inscription, permisos de copia/enseñanza, alcance de protecciones/rituales y abuso económico.</li><li>Fórmulas de magia/extremidades, armadura/resistencia y presupuestos multirregión; presión sobre Concentration e interacciones de componentes.</li><li>Vía de implementación de efectos visuales, límites de renderizado/controles de ClassicUO, recursos, información visible, rendimiento y compatibilidad.</li></ul><p>Las <a href="/Syrolands-Public/es/game-design/magic.html#open-questions">preguntas mágicas abiertas</a> anteriores, incluidas instituciones, tradiciones prohibidas y reglas de componentes, siguen sin resolverse. Esta lista no es un calendario de entrega ni elige balance numérico.</p><h2 id="evidence-limits" tabindex="-1">Límites de evidencia <a class="header-anchor" href="#evidence-limits" aria-label="Enlace permanente a &quot;Límites de evidencia&quot;">​</a></h2><p>Este batch no cambia código del juego, ajustes de ejecución, recursos, dependencias, red ni esquemas de guardado. Los controles de compilación/enlaces documentales establecen consistencia del sitio, no comportamiento de lanzamiento, aprendizaje, sensaciones de juego ni balance. De la fuente aportada no se infiere ningún ADR aceptado nuevo ni autorización de implementación.</p>',13)])])}const g=a(t,[["render",o]]);export{p as __pageData,g as default};
